seen = set()
for r in R:
    assert len(r) == 3, r
    assert r[0] not in seen, "doublon: " + r[0]
    seen.add(r[0])
head = "/* {} — généré : clé = texte français exact affiché sur le site. Modifier la valeur pour corriger une traduction. */\n"
for i, (code, name) in enumerate([("en", "English"), ("wo", "Wolof — à faire relire par un·e locuteur·rice natif·ve")], start=1):
    d = {r[0]: r[i] for r in R}
    js = head.format(name) + "window.SF_DICT = window.SF_DICT || {};\nwindow.SF_DICT." + code + " = " + json.dumps(d, ensure_ascii=False, indent=1) + ";\n"
    open(os.path.join(OUT, code + ".js"), "w", encoding="utf-8").write(js)
